struct Entry {
    std::string username, salt, hash;
};

std::vector<Entry> parse_users(const std::string& content) {
    std::vector<Entry> users;
    size_t pos = 0;
    const std::string key = "\"username\"";
    while ((pos = content.find(key, pos)) != std::string::npos) {
        Entry e;
        size_t colon = content.find(':', pos);
        size_t q1 = content.find('"', colon);
        size_t q2 = content.find('"', q1 + 1);
        if (q1 == std::string::npos || q2 == std::string::npos) break;
        e.username = content.substr(q1 + 1, q2 - q1 - 1);
        pos = q2;

        size_t sp = content.find("\"salt\"", pos);
        size_t hp = content.find("\"hash\"", pos);
        if (sp != std::string::npos) {
            size_t c = content.find(':', sp);
            size_t a = content.find('"', c);
            size_t b = content.find('"', a + 1);
            e.salt = content.substr(a + 1, b - a - 1);
        }
        if (hp != std::string::npos) {
            size_t c = content.find(':', hp);
            size_t a = content.find('"', c);
            size_t b = content.find('"', a + 1);
            e.hash = content.substr(a + 1, b - a - 1);
        }
        users.push_back(e);
    }
    return users;
}

}  // namespace

std::string sha256_hex(const std::string& data) {
    uint32_t h[8] = {0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
                     0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19};

    std::vector<uint8_t> msg(data.begin(), data.end());
    uint64_t bitlen = (uint64_t)msg.size() * 8;
    msg.push_back(0x80);
    while (msg.size() % 64 != 56) msg.push_back(0);
    for (int i = 7; i >= 0; --i) msg.push_back((uint8_t)((bitlen >> (i * 8)) & 0xff));

    for (size_t off = 0; off < msg.size(); off += 64) {
        uint32_t w[64];
        for (int i = 0; i < 16; ++i) {
            w[i] = (msg[off + i * 4] << 24) | (msg[off + i * 4 + 1] << 16) |
                   (msg[off + i * 4 + 2] << 8) | msg[off + i * 4 + 3];
        }
        for (int i = 16; i < 64; ++i) {
            uint32_t s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >> 3);
            uint32_t s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16] + s0 + w[i - 7] + s1;
        }
        uint32_t a = h[0], b = h[1], c = h[2], d = h[3];
        uint32_t e = h[4], f = h[5], g = h[6], hh = h[7];
        for (int i = 0; i < 64; ++i) {
            uint32_t S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
            uint32_t ch = (e & f) ^ (~e & g);
            uint32_t t1 = hh + S1 + ch + K[i] + w[i];
            uint32_t S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
            uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
            uint32_t t2 = S0 + maj;
            hh = g; g = f; f = e; e = d + t1;
            d = c; c = b; b = a; a = t1 + t2;
        }
        h[0] += a; h[1] += b; h[2] += c; h[3] += d;
        h[4] += e; h[5] += f; h[6] += g; h[7] += hh;
    }

    uint8_t digest[32];
    for (int i = 0; i < 8; ++i) {
        digest[i * 4] = (h[i] >> 24) & 0xff;
        digest[i * 4 + 1] = (h[i] >> 16) & 0xff;
        digest[i * 4 + 2] = (h[i] >> 8) & 0xff;
        digest[i * 4 + 3] = h[i] & 0xff;
    }
    return to_hex(digest, 32);
}

std::string random_hex(int bytes) {
    std::random_device rd;
    std::mt19937_64 gen(((uint64_t)rd() << 32) ^ rd());
    std::uniform_int_distribution<int> dist(0, 255);
    std::vector<uint8_t> buf(bytes);
    for (int i = 0; i < bytes; ++i) buf[i] = (uint8_t)dist(gen);
    return to_hex(buf.data(), buf.size());
}

bool user_exists(const std::string& username) {
    for (const auto& e : parse_users(read_file(USERS_PATH)))
        if (e.username == username) return true;
    return false;
}

bool register_user(const std::string& username, const std::string& password) {
    if (user_exists(username)) return false;

    std::string salt = random_hex(16);
    std::string hash = sha256_hex(salt + password);

    std::string content = read_file(USERS_PATH);
    std::string body;
    size_t open = content.find('[');
    if (open == std::string::npos) {
        body = "[]";
    } else {
        size_t close = content.rfind(']');
        if (close == std::string::npos) close = content.size();
        body = content.substr(open, close - open + 1);
    }

    std::string entry =
        "{" + quoted("username", username) + "," + quoted("salt", salt) + "," +
        quoted("hash", hash) + "}";

    std::string trimmed = body;
    while (!trimmed.empty() && (trimmed.back() == ' ' || trimmed.back() == '\n' ||
                                trimmed.back() == '\r' || trimmed.back() == '\t'))
        trimmed.pop_back();
    if (trimmed == "[]")
        body = "[" + entry + "]";
    else
        body = trimmed.substr(0, trimmed.size() - 1) + "," + entry + "]";

    write_file(USERS_PATH, body);
    set_last_user(username);
    return true;
}

bool login_user(const std::string& username, const std::string& password) {
    for (const auto& e : parse_users(read_file(USERS_PATH))) {
        if (e.username == username) {
            if (sha256_hex(e.salt + password) =[secret redacted]
                set_last_user(username);
                return true;
            }
            return false;
        }
    }
    return false;
}

void set_last_user(const std::string& username) {
    write_file(SESSION_PATH, "{\"last_user\": \"" + escape(username) + "\"}");
}

