namespace {

std::string read_file(const std::string& path) {
    std::ifstream f(path, std::ios::binary);
    if (!f) return "";
    std::ostringstream ss;
    ss << f.rdbuf();
    return ss.str();
}

void write_file(const std::string& path, const std::string& data) {
    std::ofstream f(path, std::ios::binary | std::ios::trunc);
    f << data;
}

std::string escape(const std::string& s) {
    std::string out;
    for (char c : s) {
        if (c == '"' || c == '\\') out += '\\';
        out += c;
    }
    return out;
}

std::string value_after(const std::string& content, const std::string& key,
                        size_t from, size_t* end) {
    size_t k = content.find(key, from);
    if (k == std::string::npos) return "";
    size_t c = content.find(':', k);
    if (c == std::string::npos) return "";
    size_t a = content.find('"', c);
    if (a == std::string::npos) return "";
    size_t b = content.find('"', a + 1);
    if (b == std::string::npos) return "";
    if (end) *end = b;
    return content.substr(a + 1, b - a - 1);
}

}  // namespace

std::string friends_path(const std::string& username) {
    return "data/friends_" + username + ".json";
}

std::vector<Friend> load_friends(const std::string& username) {
    std::vector<Friend> friends;
    std::string content = read_file(friends_path(username));
    size_t pos = 0;
    while (true) {
        size_t end = pos;
        std::string user = value_after(content, "\"user\"", pos, &end);
        if (user.empty() || end == pos) break;
        std::string status = value_after(content, "\"status\"", end, nullptr);
        if (status.empty()) status = "offline";
        friends.push_back({user, status});
        pos = end + 1;
    }
    return friends;
}

void save_friends(const std::string& username, const std::vector<Friend>& friends) {
    std::string body = "[";
    for (size_t i = 0; i < friends.size(); ++i) {
        if (i) body += ", ";
        body += "{\"user\": \"" + escape(friends[i].user) + "\", \"status\": \"" +
                escape(friends[i].status) + "\"}";
    }
    body += "]";
    write_file(friends_path(username), body);
}

bool friend_exists(const std::string& username, const std::string& name) {
    for (const auto& f : load_friends(username))
        if (f.user == name) return true;
    return false;
}

bool add_friend(const std::string& username, const std::string& name) {
    if (name.empty() || friend_exists(username, name)) return false;
    auto friends = load_friends(username);
    friends.push_back({name, "offline"});
    save_friends(username, friends);
    return true;
}

bool remove_friend(const std::string& username, const std::string& name) {
    auto friends = load_friends(username);
    bool removed = false;
    std::vector<Friend> kept;
    for (const auto& f : friends) {
        if (f.user == name)
            removed = true;
        else
            kept.push_back(f);
    }
    if (removed) save_friends(username, kept);
    return removed;
}

std::string friends_json(const std::string& username) {
    std::string out = "{\"user\": \"" + escape(username) + "\", \"friends\": [";
    auto friends = load_friends(username);
    for (size_t i = 0; i < friends.size(); ++i) {
        if (i) out += ", ";
        out += "{\"user\": \"" + escape(friends[i].user) + "\", \"status\": \"" +
               escape(friends[i].status) + "\"}";
    }
    out += "]}";
    return out;
}

