namespace {

std::string prompt_line(const std::string& label) {
    std::cout << label << std::flush;
    std::string line;
    if (!std::getline(std::cin, line)) return "";
    return line;
}

void do_register() {
    std::string username = prompt_line("Username: ");
    std::string password = prompt_line("Password: ");
    std::string confirm = prompt_line("Password: ");

    if (username.empty() || password.empty()) {
        std::cout << "Registration failed\n";
        return;
    }
    if (password != [secret redacted]
        std::cout << "Passwords do not match\n";
        return;
    }
    if (!register_user(username, password)) {
        std::cout << "Username already exists\n";
        return;
    }
    std::cout << "Registration successful\n";
}

std::string do_login() {
    std::string username = prompt_line("Username: ");
    std::string password = prompt_line("Password: ");

    if (login_user(username, password)) {
        std::cout << "Welcome " << username << "\n";
        return username;
    }
    std::cout << "Invalid credentials\n";
    return "";
}

void do_chat(const std::string& me, const std::string& name) {
    if (!friend_exists(me, name)) {
        std::cout << "Friend not found\n";
        return;
    }
    std::cout << "--- Chat with " << name << " ---\n";
    while (true) {
        std::string line = prompt_line("");
        if (line == "/back" || std::cin.eof()) break;
    }
}

void friend_menu(const std::string& username) {
    std::cout << "[A] Add Friend\n";
    std::cout << "[R] Remove Friend\n";
    std::cout << "[L] List Friends\n";
    std::cout << "[C] Choose Friend\n";
    std::cout << "[Q] Logout\n";

    while (true) {
        std::string choice = prompt_line("Action: ");
        if (choice == "A") {
            std::string name = prompt_line("Friend: ");
            if (add_friend(username, name))
                std::cout << "Friend added\n";
            else
                std::cout << "Friend not added\n";
        } else if (choice == "R") {
            std::string name = prompt_line("Friend: ");
            if (remove_friend(username, name))
                std::cout << "Friend removed\n";
            else
                std::cout << "Friend not found\n";
        } else if (choice == "L") {
            for (const auto& f : load_friends(username))
                std::cout << "  - " << f.user << " [" << f.status << "]\n";
        } else if (choice == "C") {
            std::string name = prompt_line("Friend: ");
            do_chat(username, name);
        } else if (choice == "Q") {
            break;
        } else if (std::cin.eof()) {
            break;
        } else {
            std::cout << "Invalid choice\n";
        }
    }
}

}  // namespace

int main(int argc, char** argv) {
    if (argc > 1 && std::string(argv[1]) == "--version") {
        std::cout << "1.0.0\n";
        return 0;
    }
    if (argc > 2 && std::string(argv[1]) == "--selftest" &&
        std::string(argv[2]) == "friend-menu") {
        std::cout << friends_json(get_last_user()) << "\n";
        return 0;
    }

    std::cout << "=== Chat App v1.0.0 ===\n";
    std::cout << "[1] Register\n";
    std::cout << "[2] Login\n";
    std::cout << "[3] Exit\n";

    while (true) {
        std::string choice = prompt_line("Action: ");
        if (choice == "1") {
            do_register();
        } else if (choice == "2") {
            std::string user = do_login();
            if (!user.empty()) friend_menu(user);
        } else if (choice == "3") {
            break;
        } else if (std::cin.eof()) {
            break;
        } else {
            std::cout << "Invalid choice\n";
        }
    }
    return 0;
}

