namespace {

std::string read_file(const std::string& path) {
    std::ifstream f(path, std::ios::binary);
    if (!f) return "";
    std::ostringstream ss;
    ss << f.rdbuf();
    return ss.str();
}

std::vector<std::string> split_lines(const std::string& content) {
    std::vector<std::string> lines;
    std::string cur;
    for (char c : content) {
        if (c == '\n') {
            if (!cur.empty()) lines.push_back(cur);
            cur.clear();
        } else if (c != '\r') {
            cur += c;
        }
    }
    if (!cur.empty()) lines.push_back(cur);
    return lines;
}

std::string escape(const std::string& s) {
    std::string out;
    for (char c : s) {
        if (c == '"' || c == '\\') out += '\\';
        out += c;
    }
    return out;
}

int parse_page(const std::string& line) {
    size_t sp = line.find(' ');
    if (sp == std::string::npos) return 1;
    try {
        int p = std::stoi(line.substr(sp + 1));
        return p < 1 ? 1 : p;
    } catch (...) {
        return 1;
    }
}

}  // namespace

std::string history_path(const std::string& user, const std::string& fr) {
    return "data/history/" + user + "/" + fr + ".log";
}

std::vector<std::string> load_history(const std::string& user, const std::string& fr) {
    return split_lines(read_file(history_path(user, fr)));
}

std::string now_iso8601() {
    std::time_t t = std::time(nullptr);
    std::tm tm{};
#if defined(_WIN32)
    localtime_s(&tm, &t);
#else
    localtime_r(&t, &tm);
#endif
    char buf[32];
    std::strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &tm);
    return buf;
}

void append_history(const std::string& user, const std::string& fr,
                    const std::string& sender, const std::string& text) {
    std::filesystem::create_directories("data/history/" + user);
    std::ofstream f(history_path(user, fr), std::ios::app);
    f << now_iso8601() << " | " << sender << " | " << text << "\n";
}

void clear_history(const std::string& user, const std::string& fr) {
    std::ofstream f(history_path(user, fr), std::ios::trunc);
}

std::string history_page(const std::string& user, const std::string& fr, int page) {
    auto lines = load_history(user, fr);
    std::reverse(lines.begin(), lines.end());
