}

std::string to_lower(const std::string& s) {
    std::string out = s;
    for (char& c : out) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return out;
}

std::string escape(const std::string& s) {
    std::string out;
    for (char c : s) {
        if (c == '"' || c == '\\') out += '\\';
        out += c;
    }
    return out;
}

void parse_line(const std::string& line, std::string& date, std::string& sender,
                std::string& text) {
    size_t a = line.find(" | ");
    if (a == std::string::npos) {
        date = "";
        sender = "";
        text = line;
        return;
    }
    date = line.substr(0, a);
    size_t b = line.find(" | ", a + 3);
    if (b == std::string::npos) {
        sender = "";
        text = line.substr(a + 3);
    } else {
        sender = line.substr(a + 3, b - a - 3);
        text = line.substr(b + 3);
    }
}

}  // namespace

std::string highlight(const std::string& text, const std::string& keyword) {
    std::string lowk = to_lower(keyword);
    if (lowk.empty()) return text;
    std::string low = to_lower(text);
    std::string out;
    size_t i = 0;
    while (true) {
        size_t p = low.find(lowk, i);
        if (p == std::string::npos) {
            out += text.substr(i);
            break;
        }
        out += text.substr(i, p - i);
        out += "[[" + text.substr(p, lowk.size()) + "]]";
        i = p + lowk.size();
    }
    return out;
}

std::vector<SearchHit> search_logs(const std::string& user, const std::string& keyword) {
    std::vector<SearchHit> hits;
    if (keyword.empty()) return hits;
    std::string lowk = to_lower(keyword);
    const std::string root = "data/history";
    std::error_code ec;
    if (!std::filesystem::exists(root, ec)) return hits;

    for (const auto& dir : std::filesystem::directory_iterator(root, ec)) {
        if (!dir.is_directory()) continue;
        for (const auto& entry : std::filesystem::directory_iterator(dir.path(), ec)) {
            if (!entry.is_regular_file()) continue;
            std::string fr = entry.path().stem().string();
            std::string content = read_file(entry.path().string());
            std::string line;
            std::istringstream ss(content);
            while (std::getline(ss, line)) {
                if (!line.empty() && line.back() == '\r') line.pop_back();
                if (line.empty()) continue;
                if (to_lower(line).find(lowk) == std::string::npos) continue;
                std::string date, sender, text;
                parse_line(line, date, sender, text);
                hits.push_back({fr, date, text});
