namespace concurrency {

namespace {

std::mutex g_cout_mutex;
std::atomic<bool> g_chat_active{false};

const char* kAutoPool[] = {
    "Hey, you there?",
    "How's it going?",
    "Long time no chat!",
    "Ping!",
    "Any updates?",
    "Just checking in.",
};

}  // namespace

void set_chat_active(bool active) { g_chat_active.store(active); }
bool chat_active() { return g_chat_active.load(); }

void ThreadSafeQueue::push(const Message& msg) {
    {
        std::lock_guard<std::mutex> lk(mutex_);
        if (closed_) return;
        queue_.push(msg);
    }
    cond_.notify_one();
}

bool ThreadSafeQueue::try_pop(Message& out) {
    std::lock_guard<std::mutex> lk(mutex_);
    if (queue_.empty()) return false;
    out = queue_.front();
    queue_.pop();
    return true;
}

bool ThreadSafeQueue::wait_pop(Message& out, int timeout_ms) {
    std::unique_lock<std::mutex> lk(mutex_);
    cond_.wait_for(lk, std::chrono::milliseconds(timeout_ms),
                   [this] { return !queue_.empty() || closed_; });
    if (queue_.empty()) return false;
    out = queue_.front();
    queue_.pop();
    return true;
}

std::size_t ThreadSafeQueue::size() const {
    std::lock_guard<std::mutex> lk(mutex_);
    return queue_.size();
}

void ThreadSafeQueue::close() {
    {
        std::lock_guard<std::mutex> lk(mutex_);
        closed_ = true;
    }
    cond_.notify_all();
}

ChatSimulator::ChatSimulator() = default;

ChatSimulator::~ChatSimulator() {
    stop();
    join();
}

void ChatSimulator::start(const std::vector<std::string>& friends, bool verbose) {
    verbose_.store(verbose);
    running_.store(true);
    consumer_ = std::thread(&ChatSimulator::consumer_loop, this);
    for (const auto& f : friends)
        producers_.emplace_back(&ChatSimulator::producer_loop, this, f);
}

void ChatSimulator::stop() {
    running_.store(false);
    wait_cond_.notify_all();
    queue_.close();
}

void ChatSimulator::join() {
    for (auto& t : producers_)
        if (t.joinable()) t.join();
    if (consumer_.joinable()) consumer_.join();
}

std::size_t ChatSimulator::processed() const { return processed_.load(); }

void ChatSimulator::producer_loop(std::string friend_name) {
    std::mt19937 rng(std::random_device{}() ^
                     static_cast<unsigned>(std::hash<std::thread::id>()(
                         std::this_thread::get_id())));
    std::uniform_int_distribution<int> pick(
        0, static_cast<int>(sizeof(kAutoPool) / sizeof(kAutoPool[0])) - 1);
    bool first = true;
    while (running_.load()) {
        int delay = first ? 1000 + static_cast<int>(rng() % 2000)
                          : 3000 + static_cast<int>(rng() % 3001);
        first = false;
        std::unique_lock<std::mutex> lk(wait_mutex_);
        if (wait_cond_.wait_for(lk, std::chrono::milliseconds(delay),
                                [this] { return !running_.load(); }))
            break;
        lk.unlock();
        queue_.push({friend_name, kAutoPool[pick(rng)]});
    }
}

void ChatSimulator::consumer_loop() {
    while (true) {
        Message m;
        if (queue_.wait_pop(m, 200)) {
            if (verbose_.load()) {
                std::lock_guard<std::mutex> lk(g_cout_mutex);
                std::cout << "[" << m.friend_name << "] " << m.text << "\n";
                if (g_chat_active.load()) std::cout << "> ";
                std::cout << std::flush;
            }
            processed_.fetch_add(1);
        } else if (!running_.load()) {
            while (queue_.try_pop(m)) {
                if (verbose_.load()) {
                    std::lock_guard<std::mutex> lk(g_cout_mutex);
                    std::cout << "[" << m.friend_name << "] " << m.text << "\n";
                }
                processed_.fetch_add(1);
            }
            break;
        }
    }
}

